// Captures NDJSON traces of src/host.impl.ts in the shape of spec/contract.json:
// node spec/capture.ts  → spec/traces/run-<n>.ndjson
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import createHost from '../src/host.impl.ts';

type H = Awaited<ReturnType<typeof createHost>>;
const CARTS = ['a', 'b'];

async function observe(h: H) {
  const flight = await h.inFlight();
  const carts: Record<string, unknown> = {};
  for (const id of CARTS) {
    const v = await h.cart(id);
    const own = flight.filter((m) => m.from === id || m.to === id);
    if (own.length > 1) throw new Error(`cart ${id} has ${own.length} messages in transit`);
    carts[id] = { status: v ? v.status : 'none', items: v ? v.items : 0, msg: own.length ? own[0].action : null };
  }
  const { available, reserved } = await h.stock();
  const { charged, declining } = await h.payments();
  return { carts, available, reserved, charged, declining };
}

async function step(h: H, action: string, data: { cart?: string }) {
  const cart = data.cart as string;
  switch (action) {
    case 'OPEN': return h.open(cart);
    case 'ADD': return h.add(cart);
    case 'CHECKOUT': return h.checkout(cart);
    case 'CANCEL': return h.cancel(cart);
    case 'DECLINE_CARDS': return h.declineCards();
    case 'ACCEPT_CARDS': return h.acceptCards();
    case 'DELIVER': {
      const m = (await h.inFlight()).find((x) => x.from === cart || x.to === cart);
      if (m) await h.deliver(m.id);
      return;
    }
  }
}

const ACTIONS = ['OPEN', 'ADD', 'CHECKOUT', 'CANCEL', 'DECLINE_CARDS', 'ACCEPT_CARDS', 'DELIVER', 'DELIVER', 'DELIVER'];
let seed = 11;
const rnd = (n: number) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };

const dir = new URL('./traces/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });
for (let run = 0; run < 60; run++) {
  const h = await createHost();
  const lines: string[] = [];
  for (let i = 0; i < 40; i++) {
    const action = ACTIONS[rnd(ACTIONS.length)];
    const data = action.endsWith('_CARDS') ? {} : { cart: CARTS[rnd(CARTS.length)] };
    const pre = await observe(h);
    await step(h, action, data);
    lines.push(JSON.stringify({ pre, action, data, post: await observe(h) }));
  }
  writeFileSync(new URL(`run-${run}.ndjson`, dir), lines.join('\n') + '\n');
}

