  let seed = 7;
  const rnd = (n: number) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };
  for (let run = 0; run < 500; run++) {
    const h = await createHost();
    const ids = ['a', 'b', 'c', 'd'];
    for (let step = 0; step < 40; step++) {
      const k = rnd(8);
      const c = ids[rnd(ids.length)];
      if (k === 0) await h.open(c);
      else if (k === 1) await h.add(c);
      else if (k === 2) await h.checkout(c);
      else if (k === 3) await h.cancel(c);
      else if (k === 4) await (rnd(2) ? h.declineCards() : h.acceptCards());
      else {
        const f = await h.inFlight();
        if (f.length) await h.deliver(f[rnd(f.length)].id);
      }
      const st = await h.stock();
      assert.equal(st.available + st.reserved, 2);
      assert.ok(st.available >= 0 && st.reserved >= 0);
    }
    await h.deliverAll();
    let paidUnits = 0;
    for (const c of ids) {
      const v = await h.cart(c);
      if (v?.status === 'paid') paidUnits += v.items;
      assert.ok(!v || !['reserving', 'paying', 'cancelling'].includes(v.status));
    }
    assert.equal((await h.stock()).reserved, paidUnits);
    assert.equal((await h.payments()).charged, paidUnits);
  }
});

