      DELIVER_REFUND: intent(cartSchema, cartDomain),
      DECLINE_CARDS: intent({}, [{}]),
      ACCEPT_CARDS: intent({}, [{}]),
      DELIVER: intent(cartSchema, cartDomain),
    },
    acceptors: {
      OPEN: (model) => ({ cart }, { reject, next, unchanged }) => {
        const c = model.carts[cart];
        if (!c) return reject('unknown-cart');
        if (c.status !== 'none') return reject('cart-exists');
        setCart(model, next, cart, { status: 'open', items: 0, msg: null, refund: false });
        unchanged('available', 'reserved', 'charged', 'declining');
      },
      ADD: (model) => ({ cart }, { reject, next, unchanged }) => {
        const c = model.carts[cart];
        if (!c || c.status === 'none') return reject('no-such-cart');
        if (c.status !== 'open') return reject('not-open');
        if (c.items >= MAX_ITEMS) return reject('cart-full');
        setCart(model, next, cart, { items: c.items + 1 });
        unchanged('available', 'reserved', 'charged', 'declining');
      },
      CHECKOUT: (model) => ({ cart }, { reject, next, unchanged }) => {
        const c = model.carts[cart];
        if (!c || c.status === 'none') return reject('no-such-cart');
        if (c.status !== 'open') return reject('not-open');
        if (c.items < 1) return reject('cart-empty');
        setCart(model, next, cart, { status: 'reserving', msg: 'Reserve' });
        unchanged('available', 'reserved', 'charged', 'declining');
      },
      CANCEL: (model) => ({ cart }, { reject, next, unchanged }) => {
        const c = model.carts[cart];
        if (!c || c.status === 'none') return reject('no-such-cart');
        if (c.status === 'open') setCart(model, next, cart, { status: 'cancelled' });
        else if (c.status === 'reserving') setCart(model, next, cart, { status: 'cancelling' });
        else if (c.status === 'paying') return reject('payment-in-progress');
        else return reject('not-cancellable');
        unchanged('available', 'reserved', 'charged', 'declining');
      },
      RETURN: (model) => ({ cart }, { reject, next, unchanged }) => {
        const c = model.carts[cart];
        if (!c || c.status === 'none') return reject('no-such-cart');
        if (c.status !== 'paid') return reject('not-paid');
        setCart(model, next, cart, { status: 'returned', msg: 'Release', refund: true });
        unchanged('available', 'reserved', 'charged', 'declining');
      },
      DELIVER_REFUND: (model) => ({ cart }, { reject, next, unchanged }) => {
        const c = model.carts[cart];
        if (!c || !c.refund) return reject('no-refund-in-transit');
        next.charged = model.charged - c.items;
        setCart(model, next, cart, { refund: false });
        unchanged('available', 'reserved', 'declining');
      },
      DECLINE_CARDS: (model) => (_p, { reject, next, unchanged }) => {
        if (model.declining) return reject('already-declining');
        next.declining = true;
        unchanged('carts', 'available', 'reserved', 'charged');
      },
      ACCEPT_CARDS: (model) => (_p, { reject, next, unchanged }) => {
        if (!model.declining) return reject('already-accepting');
        next.declining = false;
        unchanged('carts', 'available', 'reserved', 'charged');
      },
      DELIVER: (model) => ({ cart }, { reject, next, unchanged }) => {
        const c = model.carts[cart];
        if (!c || c.msg === null) return reject('nothing-in-transit');
        switch (c.msg) {
          // ── to the inventory ──
          case 'Reserve':
            if (c.items <= model.available) {
              next.available = model.available - c.items;
              next.reserved = model.reserved + c.items;
              setCart(model, next, cart, { msg: 'Reserved' });
            } else {
              setCart(model, next, cart, { msg: 'OutOfStock' });
              unchanged('available', 'reserved');
            }
            unchanged('charged', 'declining');
            return;
          case 'Release':
            next.available = model.available + c.items;
            next.reserved = model.reserved - c.items;
            setCart(model, next, cart, { msg: null });
            unchanged('charged', 'declining');
            return;
          // ── to the payment service ──
          case 'Charge':
            if (model.declining || model.charged + c.items > CHARGE_LIMIT) {
              setCart(model, next, cart, { msg: 'Declined' });
              unchanged('charged');
            } else {
              next.charged = model.charged + c.items;
              setCart(model, next, cart, { msg: 'Charged' });
            }
            unchanged('available', 'reserved', 'declining');
            return;
          // ── to the cart ──
          case 'Reserved':
            if (c.status === 'reserving') setCart(model, next, cart, { status: 'paying', msg: 'Charge' });
            else if (c.status === 'cancelling') setCart(model, next, cart, { status: 'cancelled', msg: 'Release' });
            else setCart(model, next, cart, { msg: null });
            break;
          case 'OutOfStock':
            if (c.status === 'reserving') setCart(model, next, cart, { status: 'failed', msg: null });
            else if (c.status === 'cancelling') setCart(model, next, cart, { status: 'cancelled', msg: null });
            else setCart(model, next, cart, { msg: null });
            break;
          case 'Charged':
            setCart(model, next, cart, c.status === 'paying' ? { status: 'paid', msg: null } : { msg: null });
            break;
          case 'Declined':
            setCart(model, next, cart, c.status === 'paying' ? { status: 'failed', msg: 'Release' } : { msg: null });
            break;
          default:
            return reject('unknown-message');
        }
        unchanged('available', 'reserved', 'charged', 'declining');
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  OPEN: (data = {}) => intents.OPEN(data),
  ADD: (data = {}) => intents.ADD(data),
  CHECKOUT: (data = {}) => intents.CHECKOUT(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
  DECLINE_CARDS: (data = {}) => intents.DECLINE_CARDS(data),
  ACCEPT_CARDS: (data = {}) => intents.ACCEPT_CARDS(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

