'use strict';
// SAM v2 strict spec of src/host.impl.ts, over two carts 'a' and 'b'.
//
// Abstraction of the network: every cart has at most one message of its own
// flow in transit at a time (Reserve → Reserved|OutOfStock → Charge →
// Charged|Declined, and Release), so the network is the per-cart field `msg`
// (null when none). DELIVER{cart} delivers that cart's message; since the
// carts' messages are independent, firing DELIVER in any order covers every
// delivery order of the real network. A returned cart also has its Refund in
// transit beside its Release: that second slot is the per-cart flag `refund`,
// delivered by DELIVER_REFUND{cart}.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const STOCK = 2;
const MAX_ITEMS = 2;
const CHARGE_LIMIT = 4;
const CARTS = ['a', 'b'];

// status: 'none' (never opened) | 'open' | 'reserving' | 'paying' | 'paid' | 'failed' | 'cancelling' | 'cancelled' | 'returned'
const NO_CART = { status: 'none', items: 0, msg: null, refund: false };
const INITIAL_STATE = {
  carts: { a: NO_CART, b: NO_CART },
  available: STOCK,
  reserved: 0,
  charged: 0,
  declining: false,
};

const cartDomain = CARTS.map((cart) => ({ cart }));
const cartSchema = { cart: { type: 'string' } };
const intent = (schema, domain) => ({ action: (data = {}) => ({ ...data }), schema, domain });
const setCart = (model, next, cart, patch) => {
  next.carts = { ...model.carts, [cart]: { ...model.carts[cart], ...patch } };
};

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      carts: { type: 'object' },
      available: { type: 'number' },
