const paidUnits = (s) => sum(carts(s).filter((c) => c.status === 'paid'));
// units the inventory holds for a cart: reserved and not yet given back
const holds = (c) => c.msg === 'Reserved' || c.msg === 'Release' || c.status === 'paying' || c.status === 'paid';

