    if (c.status !== 'declined') return refuse(`cart is ${c.status}`);
    c.status = 'paying';
    this.send(id, PAYMENTS, 'Charge', { from: id, amount: c.items });
    return OK;
  }

  async abandon(id: string): Promise<Outcome> {
    const c = this.carts.get(id);
    if (!c) return refuse('no such cart');
    if (c.status !== 'declined') return refuse(`cart is ${c.status}`);
