import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('happy path', async () => {
  const h = await createHost();
  assert.deepEqual(await h.open('a'), { ok: true });
  assert.equal((await h.open('a')).ok, false);
  assert.equal((await h.checkout('a')).ok, false);
  await h.add('a');
  await h.add('a');
  assert.equal((await h.add('a')).ok, false);
  assert.deepEqual(await h.checkout('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'reserving', items: 2 });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual(
    { from: msgs[0].from, to: msgs[0].to, action: msgs[0].action, data: msgs[0].data },
    { from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 2 } },
  );
  await h.deliver(msgs[0].id);
  assert.equal((await h.cart('a'))!.status, 'reserving');
  const [reply] = await h.inFlight();
  assert.equal(reply.action, 'Reserved');
  await h.deliver(reply.id);
  assert.equal((await h.cart('a'))!.status, 'paying');
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'paid', items: 2 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
});

test('unknown cart', async () => {
  const h = await createHost();
  assert.equal(await h.cart('x'), null);
  for (const c of ['add', 'checkout', 'cancel'] as const) assert.equal((await h[c]('x')).ok, false);
});

test('declined cart keeps units; abandon releases them', async () => {
  const h = await createHost();
  assert.equal((await h.acceptCards()).ok, false);
  assert.deepEqual(await h.declineCards(), { ok: true });
  assert.equal((await h.declineCards()).ok, false);
  await h.open('a'); await h.add('a');
  assert.equal((await h.retry('a')).ok, false);
  assert.equal((await h.abandon('a')).ok, false);
  await h.checkout('a');
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'declined', items: 1 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 1 });
  for (const c of ['add', 'checkout', 'cancel', 'returnCart'] as const) assert.equal((await h[c]('a')).ok, false);
  assert.deepEqual(await h.retry('a'), { ok: true });
  assert.equal((await h.cart('a'))!.status, 'paying');
  assert.equal((await h.abandon('a')).ok, false);
  await h.deliverAll();
  assert.equal((await h.cart('a'))!.status, 'declined');
  assert.deepEqual(await h.abandon('a'), { ok: true });
  assert.equal((await h.cart('a'))!.status, 'failed');
  assert.equal((await h.retry('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: true });
});

test('out of stock', async () => {
  const h = await createHost();
  for (const c of ['a', 'b']) { await h.open(c); await h.add(c); await h.add(c); await h.checkout(c); }
  await h.deliverAll();
  const s = [(await h.cart('a'))!.status, (await h.cart('b'))!.status].sort();
  assert.deepEqual(s, ['failed', 'paid']);
});

test('cancel while reserving gives units back', async () => {
  const h = await createHost();
  await h.open('a'); await h.add('a'); await h.checkout('a');
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.equal((await h.cart('a'))!.status, 'cancelling');
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.equal((await h.cart('a'))!.status, 'cancelled');
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.equal((await h.payments()).charged, 0);
});

test('return a paid cart', async () => {
  const h = await createHost();
  await h.open('a'); await h.add('a'); await h.add('a');
  assert.equal((await h.returnCart('a')).ok, false);
  assert.equal((await h.returnCart('x')).ok, false);
  await h.checkout('a');
  await h.deliverAll();
  assert.deepEqual(await h.returnCart('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'returned', items: 2 });
  const msgs = (await h.inFlight()).map((m) => ({ from: m.from, to: m.to, action: m.action, data: m.data }));
  assert.deepEqual(msgs.sort((x, y) => x.to.localeCompare(y.to)), [
    { from: 'a', to: 'inventory', action: 'Release', data: { qty: 2 } },
    { from: 'a', to: 'payments', action: 'Refund', data: { amount: 2 } },
  ]);
  for (const c of ['add', 'checkout', 'cancel', 'returnCart'] as const) assert.equal((await h[c]('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  assert.deepEqual(await h.inFlight(), []);
});

test('payment timeout, then charge goes through: refund', async () => {
  const h = await createHost();
  await h.open('a'); await h.add('a'); await h.add('a');
  assert.equal((await h.paymentTimeout('a')).ok, false);
  await h.checkout('a');
  assert.equal((await h.paymentTimeout('a')).ok, false); // reserving
  await h.deliver((await h.inFlight())[0].id); // Reserve
  await h.deliver((await h.inFlight())[0].id); // Reserved → paying, Charge sent
  assert.equal((await h.cart('a'))!.status, 'paying');
  assert.deepEqual(await h.paymentTimeout('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'abandoning', items: 2 });
  for (const c of ['add', 'checkout', 'cancel', 'returnCart', 'retry', 'abandon', 'paymentTimeout'] as const) {
    assert.equal((await h[c]('a')).ok, false, c);
  }
  const release = (await h.inFlight()).find((m) => m.action === 'Release')!;
  assert.deepEqual(release.data, { qty: 2 });
  await h.deliver(release.id);
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  await h.deliver((await h.inFlight())[0].id); // Charge accepted
  assert.equal((await h.payments()).charged, 2);
  await h.deliver((await h.inFlight())[0].id); // Charged → Refund
  assert.equal((await h.cart('a'))!.status, 'failed');
  const [refund] = await h.inFlight();
  assert.deepEqual({ to: refund.to, action: refund.action, data: refund.data }, { to: 'payments', action: 'Refund', data: { amount: 2 } });
  await h.deliverAll();
  assert.deepEqual(await h.payments(), { charged: 0, declining: false });
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
});

test('payment timeout, then declined: failed, nothing charged', async () => {
  const h = await createHost();
  await h.declineCards();
  await h.open('a'); await h.add('a'); await h.checkout('a');
  await h.deliver((await h.inFlight())[0].id);
