1	'use strict';
2	// SAM v2 strict spec of src/host.impl.ts, over two carts 'a' and 'b'.
3	//
4	// Abstraction of the network: every cart has at most one message of its own
5	// flow in transit at a time (Reserve → Reserved|OutOfStock → Charge →
6	// Charged|Declined, and Release), so the network is the per-cart field `msg`
7	// (null when none). DELIVER{cart} delivers that cart's message; since the
8	// carts' messages are independent, firing DELIVER in any order covers every
9	// delivery order of the real network. A returned cart also has its Refund in
10	// transit beside its Release: that second slot is the per-cart flag `refund`,
11	// delivered by DELIVER_REFUND{cart}.
12	
13	const { createInstance } = require('@cognitive-fab/sam-pattern');
14	
15	const instance = createInstance({ strict: true, hasAsyncActions: false });
16	
17	const STOCK = 2;
18	const MAX_ITEMS = 2;
19	const CHARGE_LIMIT = 4;
20	const CARTS = ['a', 'b'];
21	
22	// status: 'none' (never opened) | 'open' | 'reserving' | 'paying' | 'paid' | 'failed' | 'cancelling' | 'cancelled' | 'returned' | 'declined'
23	const NO_CART = { status: 'none', items: 0, msg: null, refund: false };
24	const INITIAL_STATE = {
25	  carts: { a: NO_CART, b: NO_CART },
26	  available: STOCK,
27	  reserved: 0,
28	  charged: 0,
29	  declining: false,
30	};
31	
32	const cartDomain = CARTS.map((cart) => ({ cart }));
33	const cartSchema = { cart: { type: 'string' } };
34	const intent = (schema, domain) => ({ action: (data = {}) => ({ ...data }), schema, domain });
35	const setCart = (model, next, cart, patch) => {
36	  next.carts = { ...model.carts, [cart]: { ...model.carts[cart], ...patch } };
37	};
38	
39	const control = instance({
40	  initialState: { ...INITIAL_STATE },
41	  component: {
42	    modelShape: {
43	      carts: { type: 'object' },
44	      available: { type: 'number' },
45	      reserved: { type: 'number' },
46	      charged: { type: 'number' },
47	      declining: { type: 'boolean' },
48	    },
49	    actions: {
50	      OPEN: intent(cartSchema, cartDomain),
51	      ADD: intent(cartSchema, cartDomain),
