// Rules the brief requires of the checkout, over spec/checkout.spec.cjs.
const STOCK = 2;
const CHARGE_LIMIT = 4;
const TRANSIENT = ['reserving', 'paying', 'cancelling'];

const carts = (s) => Object.values(s.carts);
const sum = (xs) => xs.reduce((n, c) => n + c.items, 0);
const quiet = (s) => carts(s).every((c) => c.msg === null && !c.refund);
const paidUnits = (s) => sum(carts(s).filter((c) => c.status === 'paid'));
// a declined cart keeps its units reserved until retried or abandoned
const heldUnits = (s) => sum(carts(s).filter((c) => c.status === 'paid' || c.status === 'declined'));
// units the inventory holds for a cart: reserved and not yet given back
const holds = (c) => c.msg === 'Reserved' || c.msg === 'Release' || ['paying', 'paid', 'declined'].includes(c.status);

export const stateInvariants = [
  { name: 'stock-conserved', pred: (s) => s.available + s.reserved === STOCK && s.available >= 0 && s.reserved >= 0 },
  { name: 'charge-limit', pred: (s) => s.charged >= 0 && s.charged <= CHARGE_LIMIT },
  { name: 'quiescent-reserved-is-paid-and-declined-units', pred: (s) => !quiet(s) || s.reserved === heldUnits(s) },
  { name: 'declined-is-settled', pred: (s) => carts(s).every((c) => c.status !== 'declined' || c.msg === null) },
  { name: 'quiescent-charged-is-paid-units', pred: (s) => !quiet(s) || s.charged === paidUnits(s) },
  { name: 'reserved-accounted-per-cart', pred: (s) => s.reserved === sum(carts(s).filter(holds)) },
  { name: 'charged-accounted-per-cart', pred: (s) => s.charged === sum(carts(s).filter((c) => c.status === 'paid' || c.msg === 'Charged' || c.refund)) },
  { name: 'refund-only-for-returned', pred: (s) => carts(s).every((c) => !c.refund || c.status === 'returned') },
  { name: 'transient-cart-is-waiting', pred: (s) => carts(s).every((c) => !TRANSIENT.includes(c.status) || c.msg !== null) },
  { name: 'items-bounded', pred: (s) => carts(s).every((c) => c.items >= 0 && c.items <= 2) },
];

export const transitionInvariants = [
  {
    name: 'paid-only-after-reserve-and-charge',
    pred: (pre, action, data, post) =>
      Object.keys(post.carts).every((k) => {
        const a = pre.carts[k], b = post.carts[k];
        if (b.status !== 'paid' || a.status === 'paid') return true;
        return action === 'DELIVER' && data.cart === k && a.status === 'paying' && a.msg === 'Charged';
      }),
  },
  {
    name: 'paid-leaves-only-by-return',
    pred: (pre, action, data, post) =>
      Object.keys(pre.carts).every((k) => pre.carts[k].status !== 'paid' || post.carts[k].status === 'paid' ||
        (action === 'RETURN' && data.cart === k && post.carts[k].status === 'returned')),
  },
  {
    name: 'declined-only-by-a-declined-charge',
    pred: (pre, action, data, post) =>
      Object.keys(post.carts).every((k) => {
        const a = pre.carts[k], b = post.carts[k];
        if (b.status !== 'declined' || a.status === 'declined') return true;
        return action === 'DELIVER' && data.cart === k && a.status === 'paying' && a.msg === 'Declined';
      }),
  },
  {
    name: 'declined-leaves-only-by-retry-or-abandon',
    pred: (pre, action, data, post) =>
      Object.keys(pre.carts).every((k) => pre.carts[k].status !== 'declined' || post.carts[k].status === 'declined' ||
        (data.cart === k && ((action === 'RETRY' && post.carts[k].status === 'paying') ||
          (action === 'ABANDON' && post.carts[k].status === 'failed')))),
  },
  {
    name: 'returned-is-final',
    pred: (pre, _a, _d, post) => Object.keys(pre.carts).every((k) => pre.carts[k].status !== 'returned' || post.carts[k].status === 'returned'),
  },
  {
    name: 'items-frozen-after-checkout',
    pred: (pre, _a, _d, post) =>
      Object.keys(pre.carts).every((k) => ['none', 'open'].includes(pre.carts[k].status) || pre.carts[k].items === post.carts[k].items),
  },
];

