async function observe(h: H) {
  const flight = await h.inFlight();
  const carts: Record<string, unknown> = {};
  for (const id of CARTS) {
    const v = await h.cart(id);
    const own = flight.filter((m) => (m.from === id || m.to === id) && m.action !== 'Refund');
    const refunds = flight.filter((m) => m.from === id && m.action === 'Refund');
    if (own.length > 1 || refunds.length > 1) throw new Error(`cart ${id} has too many messages in transit`);
    carts[id] = {
      status: v ? v.status : 'none',
      items: v ? v.items : 0,
      msg: own.length ? own[0].action : null,
      refund: refunds.length === 1,
    };
  }
  const { available, reserved } = await h.stock();
  const { charged, declining } = await h.payments();
  return { carts, available, reserved, charged, declining };
}

async function step(h: H, action: string, data: { cart?: string }) {
  const cart = data.cart as string;
  switch (action) {
    case 'OPEN': return h.open(cart);
    case 'ADD': return h.add(cart);
    case 'CHECKOUT': return h.checkout(cart);
    case 'CANCEL': return h.cancel(cart);
    case 'RETURN': return h.returnCart(cart);
    case 'RETRY': return h.retry(cart);
    case 'ABANDON': return h.abandon(cart);
    case 'DECLINE_CARDS': return h.declineCards();
    case 'ACCEPT_CARDS': return h.acceptCards();
    case 'DELIVER_REFUND': {
      const m = (await h.inFlight()).find((x) => x.from === cart && x.action === 'Refund');
      if (m) await h.deliver(m.id);
      return;
    }
    case 'DELIVER': {
      const m = (await h.inFlight()).find((x) => (x.from === cart || x.to === cart) && x.action !== 'Refund');
      if (m) await h.deliver(m.id);
      return;
    }
  }
}

const ACTIONS = ['OPEN', 'ADD', 'CHECKOUT', 'CANCEL', 'DECLINE_CARDS', 'ACCEPT_CARDS', 'RETURN', 'DELIVER_REFUND', 'RETRY', 'ABANDON', 'DELIVER', 'DELIVER', 'DELIVER'];
let seed = 11;
const rnd = (n: number) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };

const dir = new URL('./traces/', import.meta.url);

