// Scripted prefixes that drive a cart into paying (and a timed-out payment)
// before the random walk, which rarely gets there on its own.
const toPaying = (c: string): [string, string?][] => [['OPEN', c], ['ADD', c], ['CHECKOUT', c], ['DELIVER', c], ['DELIVER', c]];
const PREFIXES: [string, string?][][] = [
  [],
  [...toPaying('a'), ['PAYMENT_TIMEOUT', 'a']],
  [['DECLINE_CARDS'], ...toPaying('a'), ['PAYMENT_TIMEOUT', 'a']],
  [...toPaying('a'), ['DELIVER', 'a'], ['PAYMENT_TIMEOUT', 'a']],
  [['DECLINE_CARDS'], ...toPaying('b'), ['DELIVER', 'b'], ['PAYMENT_TIMEOUT', 'b']],
  [...toPaying('a'), ['PAYMENT_TIMEOUT', 'a'], ['DELIVER_RELEASE', 'a'], ['OPEN', 'b'], ['ADD', 'b'], ['CHECKOUT', 'b']],
];
for (let run = 0; run < 150; run++) {
  const h = await createHost();
  const lines: string[] = [];
  const prefix = PREFIXES[run % PREFIXES.length];
  for (let i = 0; i < 40; i++) {
    const action = i < prefix.length ? prefix[i][0] : ACTIONS[rnd(ACTIONS.length)];
    const data = action.endsWith('_CARDS') ? {} : { cart: i < prefix.length ? prefix[i][1]! : CARTS[rnd(CARTS.length)] };

